const fs = require("fs");
const { clickCheckboxViaCDP } = require("../module/clickCheckbox");
const { debugLog, infoLog, errorLog } = require('../module/logger');

function solveTurnstileMin({ url, proxy, siteKey }) {
  return new Promise(async (resolve, reject) => {
    if (!url) return reject("Missing url parameter");
    if (!siteKey) return reject("Missing siteKey parameter");

    const context = await global.browser
      .createBrowserContext({
        proxyServer: proxy ? `http://${proxy.host}:${proxy.port}` : undefined,
      })
      .catch(() => null);
      
    if (!context) return reject("Failed to create browser context");

    let isResolved = false;

    const cl = setTimeout(async () => {
      if (!isResolved) {
        await context.close();
        reject("Timeout Error");
      }
    }, global.timeOut || 30000);

    infoLog(`[app] Request received for ${url} ...`);

    try {
      const page = await context.newPage();

      if (proxy?.username && proxy?.password)
        await page.authenticate({
          username: proxy.username,
          password: proxy.password,
        });

      await page.setRequestInterception(true);

      page.on("request", async (request) => {
        if (
          [url, url + "/"].includes(request.url()) &&
          request.resourceType() === "document"
        ) {
          await request.respond({
            status: 200,
            contentType: "text/html",
            body: String(
              fs.readFileSync("./src/data/fakePage.html")
            ).replace(/<site-key>/g, siteKey),
          });
        } else {
          await request.continue();
        }
      });

      await page.goto(url, {
        waitUntil: "domcontentloaded",
      });

      // ── Polling Loop ────────────────────────────────────────────────
      // Instead of just waiting for the selector to appear in the DOM, 
      // we actively check if it holds a valid token value.
      const maxMs = global.timeOut || 30000;
      const deadline = Date.now() + maxMs;
      let token = null;
      let attempts = 0;

      while (Date.now() < deadline) {
        token = await page.evaluate(() => {
          try {
            const el = document.querySelector('[name="cf-response"]');
            return el ? el.value : null;
          } catch (e) {
            return null;
          }
        }).catch(() => null);

        // If we successfully grabbed a valid token, break out of the loop
        if (token && token.length > 10) {
          break;
        }

        attempts++;
        
        // Give the widget a couple of seconds to auto-solve (Managed/Invisible mode).
        // If it hasn't solved by x attemtps, assume it's an Interactive challenge and click it.
        // We pass a short timeout (2000ms) so it doesn't block our 1s loop for 15s.
        if (attempts >= 7) {
          debugLog('[solveTurnstileMin] Challenge not auto-solved, trying to click checkbox ...');
          await clickCheckboxViaCDP(page, 2000).catch(err => {
              errorLog('[solveTurnstileMin] Click solver error:', err.message);
              return false;
          });
        }

        await new Promise(r => setTimeout(r, 1000));
      }

      isResolved = true;
      clearTimeout(cl);
      await context.close();
      
      if (!token || token.length < 10) return reject("Failed to get token");
      
      infoLog("[solveTurnstileMin] ✓ Token solved successfully.");
      return resolve(token);
    } catch (e) {
      if (!isResolved) {
        await context.close();
        clearTimeout(cl);
        reject(e.message);
      }
    }
  });
}

module.exports = solveTurnstileMin;